def gen(rng):
    def fmt(rows):
        return f"{len(rows)} {len(rows[0])}\n" + '\n'.join(rows)

    def rnd(r, c, p):
        return [''.join('1' if rng.random() < p else '0' for _ in range(c)) for _ in range(r)]

    tests = [fmt(['1']), fmt(['0']), fmt(['111', '111', '111']), fmt(['111', '101', '111']),
             fmt(['0', '0']), fmt(['1', '1', '1']), fmt(['11111']), fmt(['0110', '1111', '0110']),
             fmt(['11111', '10001', '10101', '10001', '11111']), fmt(['111', '111', '111', '111'])]
    for r, c in ((2, 2), (3, 5), (5, 3), (6, 6), (8, 7), (10, 10), (4, 12), (12, 4)):
        for p in (0.4, 0.8, 0.95):
            tests.append(fmt(rnd(r, c, p)))
    R = C = 500
    tests.append(fmt(rnd(R, C, 0.5)))
    tests.append(fmt(rnd(R, C, 0.97)))
    tests.append(fmt(['1' * C] * R))
    tests.append(fmt(['0' * C] * R))
    tests.append(fmt(rnd(R, 313, 0.9)))
